<?php require_once __DIR__.'/includes/auth.php';require_login(['admin','hod']);$rows=db()->query("SELECT a.*,c.course_code,c.course_title,u.full_name user_name FROM activity_logs a LEFT JOIN result_records r ON r.id=a.result_id LEFT JOIN courses c ON c.id=r.course_id LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 200")->fetchAll();$pageTitle='Activity Log | IFT';require __DIR__.'/includes/header.php';?><body class="portal-page"><header class="portal-header"><div class="portal-brand"><img src="assets/naits-logo.png"><div><strong>IFT Result Tracking</strong><span>Activity Log</span></div></div><a class="portal-back" href="<?=current_user()['role']==='hod'?'hod-dashboard.php':'admin-dashboard.php'?>">← Dashboard</a></header><main class="portal-main"><div class="page-title"><div><span class="kicker">AUDIT TRAIL</span><h1>Activity Log</h1><p>Movement records are append-only. Corrections are recorded as new actions.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Date / Time</th><th>Course</th><th>Action</th><th>By</th><th>Received By</th><th>Note</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('d M Y H:i',strtotime($r['created_at'])))?></td><td><strong><?=e($r['course_code']??'—')?></strong><small><?=e($r['course_title']??'')?></small></td><td><?=e($r['action'])?></td><td><?=e($r['user_name']??'System')?></td><td><?=e($r['received_by']??'—')?></td><td><?=e($r['note']??'')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No activity yet.</td></tr><?php endif;?></tbody></table></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>
